dec d ;0xff для вывода на правую часть дисплея
ldi c, image_right ;адрес правой части изображения
ldi b, 16 ;счётчик
loop_right:
  ld a, c ;читаем фрагмент
  st a, d ;выводим
  inc c ;следующий фрагмент
  dec b ;если фрагменты ещё остались, продолжаем выводить
  jnz loop_right
dec d ;0xfe для вывода на левую часть дисплея
ldi b, 16 ;обновляем счётчик
;регистр c уже содержит адрес левой части изображения
loop_left: ;то же самое, что и для правой, но для левой части
  ld a, c
  st a, d
  inc c
  dec b
  jnz loop_left
hlt ;конец
image_right db ;правая часть изображения
0b10101010,
0b01010101,
0b00000000,
0b10100000,
0b10100100,
0b10101010,
0b10101010,
0b10100100,
0b00010001,
0b01010001,
0b10010011,
0b10010101,
0b10010011,
0b00000000,
0b01010101,
0b10101010
image_left db ;левая часть изображения
0b10101010,
0b01010101,
0b00000000,
0b10100000,
0b10100100,
0b11101010,
0b10101100,
0b10100110,
0b00000000,
0b10100100,
0b11101010,
0b11101010,
0b01000100,
0b00000000,
0b01010101,
0b10101010


